<?php
declare(strict_types=1);
namespace App\Controllers\Feb;
use App\Controllers\BaseController;use App\Helpers\Auth;use App\Helpers\Csrf;use App\Helpers\Session;use App\Middleware\AuthMiddleware;use App\Models\Database;use App\Repositories\Feb\FebRepository;use App\Security\PermissionEntityRegistry;use App\Services\Feb\FebService;use App\Services\Shared\ModuleDashboardService;
final class FebController extends BaseController {
 private function repo():FebRepository{return new FebRepository(Database::getConnection());}
 private function service():FebService{return new FebService($this->repo());}
 private function guard(string $action='view'):void{AuthMiddleware::check();if(!Auth::can(PermissionEntityRegistry::FEB_REQUESTS,$action)){http_response_code(403);exit('Accès interdit');}}
 private function context(string $title,string $active,string $module='employee'):array{$m=(new ModuleDashboardService())->dashboard($module);$nav=$m['navigation'];if(!in_array('feb',array_column($nav,'key'),true)){$nav[]=['key'=>'feb','label'=>'Fiches de besoin','icon'=>'FEB','url'=>'/feb','group'=>'Dépenses','available'=>true];}return ['pageTitle'=>$title,'moduleName'=>$m['label'],'moduleCode'=>$m['code'],'moduleTheme'=>$m,'moduleNavigation'=>$nav,'activeModule'=>$active,'additionalStyles'=>['css/finea-ui.css','css/components/btp-workspace.css','css/components/feb-workspace.css']];}
 public function index():void{$this->guard();$user=(int)Auth::id();$rows=$this->repo()->listFor($user,'demander',$user);if(Auth::can(PermissionEntityRegistry::FEB_REQUESTS,'update'))$rows=array_merge($rows,$this->repo()->listFor($user,'valider'));if(Auth::can(PermissionEntityRegistry::FEB_REQUESTS,'delete'))$rows=array_merge($rows,$this->repo()->listFor($user,'payer'));$unique=[];foreach($rows as $row)$unique[(int)$row['id']]=$row;usort($unique,static fn(array $a,array $b)=>(int)$b['id']<=>(int)$a['id']);$this->view('feb/index',$this->context('Fiches d’expression de besoin','feb',(Auth::can(PermissionEntityRegistry::FEB_REQUESTS,'update')||Auth::can(PermissionEntityRegistry::FEB_REQUESTS,'delete'))?'finance':'employee')+['requests'=>array_values($unique),'canCreate'=>Auth::can(PermissionEntityRegistry::FEB_REQUESTS,'create')]);}
 public function create():void{
  $this->guard('create');
  $scope=($_GET['scope']??'chantier')==='bureau'?'bureau':'chantier';
  $chantier=(int)($_GET['chantier']??0);
  $this->redirect('/espace-employe/demandes/nouvelle?type=feb&scope='.$scope.($chantier>0?'&chantier='.$chantier:''));
 }
 public function store():void{$this->guard('create');$this->csrf();try{$id=$this->service()->create($_POST,$_FILES,(int)Auth::id());Session::flash('success','FEB enregistrée en brouillon.');$this->redirect('/feb/'.$id);}catch(\Throwable $e){Session::flash('error',$e instanceof \DomainException?$e->getMessage():'Création impossible.');$scope=($_POST['scope']??'chantier')==='bureau'?'bureau':'chantier';$this->redirect('/espace-employe/demandes/nouvelle?type=feb&scope='.$scope.($scope==='chantier'?'&chantier='.(int)($_POST['chantier_id']??0):''));}}
 public function show(string $id):void{$this->guard();$repo=$this->repo();$r=$repo->find((int)$id);$user=(int)Auth::id();$owner=$r&&(int)$r['requester_id']===$user&&(($r['scope']??'chantier')==='bureau'||$repo->hasChantierAccess($user,(int)$r['chantier_id'],'demander'));$validator=$r&&Auth::can(PermissionEntityRegistry::FEB_REQUESTS,$repo->currentStepPermission((int)$id))&&$repo->canActOnRequest($r,$user,'valider');$payer=$r&&Auth::can(PermissionEntityRegistry::FEB_REQUESTS,'delete')&&$repo->canActOnRequest($r,$user,'payer');if(!$r||(!$owner&&!$validator&&!$payer)){http_response_code(404);exit('FEB introuvable');}$this->view('feb/show',$this->context('FEB '.($r['reference']?:'#'.$r['id']),'feb',($validator||$payer)?'finance':'employee')+['request'=>$r,'csrf'=>Csrf::token(),'isOwner'=>$owner,'canDecide'=>$validator&&$r['status']==='soumis'&&(!$r['current_step_id']?false:($repo->stepAssignedUser((int)$r['current_step_id'])===null||$repo->stepAssignedUser((int)$r['current_step_id'])===$user)),'canPay'=>$payer]);}
 public function download(string $id,string $documentId):void{$this->guard();$repo=$this->repo();$r=$repo->find((int)$id);$user=(int)Auth::id();$allowed=$r&&(((int)$r['requester_id']===$user&&(($r['scope']??'chantier')==='bureau'||$repo->hasChantierAccess($user,(int)$r['chantier_id'],'demander')))||(Auth::can(PermissionEntityRegistry::FEB_REQUESTS,'update')&&$repo->canActOnRequest($r,$user,'valider'))||(Auth::can(PermissionEntityRegistry::FEB_REQUESTS,'delete')&&$repo->canActOnRequest($r,$user,'payer')));$doc=$allowed?$repo->document((int)$id,(int)$documentId):null;$path=$doc?(new \App\Services\Feb\FebUploadService())->resolve((string)$doc['storage_name']):null;if(!$doc||!$path){http_response_code(404);exit('Document introuvable');}$name=preg_replace('/[^A-Za-z0-9._-]+/','-',basename((string)$doc['original_name']))?:('document-'.$documentId);header('Content-Type: application/octet-stream');header('X-Content-Type-Options: nosniff');header('Content-Disposition: attachment; filename="'.$name.'"');header('Content-Length: '.filesize($path));readfile($path);exit;}
 public function submit(string $id):void{$this->guard('create');$this->csrf();$this->run(fn()=> $this->service()->submit((int)$id,(int)Auth::id()),'/feb/'.$id,'FEB soumise.');}
 public function document(string $id):void{$this->guard('create');$this->csrf();$this->run(fn()=> $this->service()->addDocument((int)$id,$_FILES['attachment']??[],(int)Auth::id()),'/feb/'.$id,'Complément ajouté.');}
 public function cancel(string $id):void{$this->guard('create');$this->csrf();$this->run(fn()=> $this->service()->cancel((int)$id,(int)Auth::id()),'/feb/'.$id,'FEB annulée.');}
 public function decide(string $id):void{$this->guard($this->repo()->currentStepPermission((int)$id));$this->csrf();$this->run(fn()=> $this->service()->decide((int)$id,(string)($_POST['decision']??''),(string)($_POST['comment']??''),(int)Auth::id()),'/feb/'.$id,'Décision enregistrée.');}
 public function pay(string $id):void{$this->guard('delete');$this->csrf();$this->run(fn()=> $this->service()->pay((int)$id,$_POST,(int)Auth::id()),'/feb/'.$id,'Paiement enregistré.');}
 private function csrf():void{if(!Csrf::verify($_POST['_csrf_token']??null)){http_response_code(403);exit('Jeton CSRF invalide.');}}
 private function run(callable $fn,string $url,string $ok):void{try{$fn();Session::flash('success',$ok);}catch(\Throwable $e){Session::flash('error',$e instanceof \DomainException?$e->getMessage():'Opération impossible.');}$this->redirect($url);}
}
